"""Migrated Meridian CRM 4.2 opportunity_pipeline workflow."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric-context coercion for the fields used by this workflow."""
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _has_lost_reason(record: dict) -> bool:
    """LOST_RSN <> '' is true only for a non-empty string."""
    value = record.get("LOST_RSN", "")
    return isinstance(value, str) and value != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire one opportunity_pipeline workflow event without mutating record."""
    result_record = dict(record)

    if state == "P" and event == "qualify":
        # NVL(AMT, 0) > 0; missing and empty AMT are numeric zero.
        if _numeric(record.get("AMT", 0)) > Decimal("0"):
            result_record["STAGE_PCT"] = "25"
            return {
                "state": "Q",
                "record": result_record,
                "audits": ["OPP_QUAL"],
                "notifies": [],
                "matched": True,
            }

    if state == "Q" and event == "advance":
        result_record["STAGE_PCT"] = "60"
        return {
            "state": "N",
            "record": result_record,
            "audits": [],
            "notifies": [],
            "matched": True,
        }

    if state == "N" and event == "close_won":
        # This is plain inequality against the date sentinel literal.
        if record.get("CLOSE_DT", "") != "00000000":
            result_record["STAGE_PCT"] = "100"
            return {
                "state": "W",
                "record": result_record,
                "audits": ["OPP_WON"],
                "notifies": ["won_deal"],
                "matched": True,
            }

    if state == "P" and event == "close_lost" and _has_lost_reason(record):
        result_record["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": result_record,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    if state == "Q" and event == "close_lost" and _has_lost_reason(record):
        result_record["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": result_record,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    if state == "N" and event == "close_lost" and _has_lost_reason(record):
        result_record["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": result_record,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
